-- Hosbah: a cron job of a git-deployed site (app). cron is a 5-field expression read in timezone
-- (IANA); command is a shell line that runs INSIDE the live release's web container (the agent's
-- app.exec: docker exec … sh -lc <command>, one argv element, never a host shell). The scheduler
-- (internal/schedules) claims rows whose next_run_at is due and moves next_run_at on BEFORE it
-- runs anything, so a crash never fires one twice. next_run_at is null while disabled.
-- overlap 'skip': a fire while the previous run is still going is recorded as skipped.
-- last_run_at / last_status mirror the newest run. Rows go with their app.
ALTER TABLE schedules ADD CONSTRAINT schedules_name_check CHECK (length(name) BETWEEN 1 AND 80);
ALTER TABLE schedules ADD CONSTRAINT schedules_cron_check CHECK (length(cron) BETWEEN 9 AND 200);
ALTER TABLE schedules ADD CONSTRAINT schedules_timezone_check CHECK (length(timezone) BETWEEN 1 AND 64);
ALTER TABLE schedules ADD CONSTRAINT schedules_command_check CHECK (length(command) BETWEEN 1 AND 1000 AND command !~ '[\n\r]');
ALTER TABLE schedules ADD CONSTRAINT schedules_timeout_check CHECK (timeout_seconds BETWEEN 10 AND 3600);
ALTER TABLE schedules ADD CONSTRAINT schedules_overlap_check CHECK (overlap IN ('skip'));
ALTER TABLE schedules ADD CONSTRAINT schedules_last_status_check CHECK (last_status IS NULL OR last_status IN ('queued', 'running', 'succeeded', 'failed', 'timeout', 'skipped'));
